      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    // Dead-end escape: if ≤1 valid next token, roll back to last complete state and close
    var narrow := helpers.DeadEndDetection(parser, currentConstrainedOut, 2);
    if narrow {
      var rb_gen, rb_cur := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
      generated := rb_gen;
      currentConstrainedOut := rb_cur;
      if parser.IsCompletePrefix(currentConstrainedOut) {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
        // Loop continues: model will generate outside the now-closed span
      } else {
        // No complete rollback state available: force-close with remaining budget
        var cg, ci, cc := helpers.CloseSpanWithinBudget(
          lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
        );
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := maxSteps;
        break;
      }
    } else {
      // Normal constrained generation with repetition penalty to discourage token reuse
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeRepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 4.0, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
