    }
  }
}

// Final cleanup: close any remaining open span with rollback-first strategy
if insideConstrainedOut && steps < maxSteps {
  var remaining3: nat := maxSteps - steps;
  // Rollback to last complete expression so close doesn't get stuck in !-loops
  var rb_gen, rb_cur := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
  generated := rb_gen;
  currentConstrainedOut := rb_cur;
  if parser.IsCompletePrefix(currentConstrainedOut) && remaining3 >= 1 {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else if remaining3 > 0 {
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining3
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
